import re
BASE = 'https://docs.legis.wisconsin.gov'
REF = re.compile(r'(?is)<a class="reference"[^>]*>.*?</a>|<span class="reference">.*?</span>')
def sections():
    kind, index = fetch(BASE + '/statutes/statutes')
    chapters = list(dict.fromkeys(re.findall(r'href=["\'](/document/statutes/\d+[a-z]?)["\']', index)))
    log('chapters: ' + str(len(chapters)))
    done = set()
    for ch in chapters:
        try:
            kind, toc = fetch(BASE + ch)
        except Exception as e:
            log('chapter failed ' + ch + ' ' + repr(e)); continue
        for sid in dict.fromkeys(re.findall(r'href=["\']/document/statutes/(\d+[a-z]?\.\d+[a-z]?)["\']', toc)):
            if sid in done:
                continue
            try:
                kind, page = fetch(BASE + '/document/statutes/' + sid)       # serves the whole subchapter: read every section on it
            except Exception as e:
                log('section failed ' + sid + ' ' + repr(e)); continue
            page = REF.sub('', page)                                          # the margin reference repeats each number
            for s in dict.fromkeys(re.findall(r'class="qsatxt_[^"]*"[^>]*data-section="([^"]+)"', page)):
                if s in done:
                    continue
                text = block_text(page, cls='qsatxt*', attr=('data-section', s), every=True)
                if not text.startswith(s + ' '):    # only part of it on this page (no numbered title line): read it from its own page
                    continue
                done.add(s)
                hist = block_text(page, cls='qsnote_history', attr=('data-section', s), every=True)
                m = re.match(re.escape(s) + r'\s+(.+?\.)(?:\s|$)', text.split('\n', 1)[0])
                yield {'id': s, 'heading': m.group(1) if m else '', 'text': text + ('\n' + hist if hist else ''),
                       'url': BASE + '/document/statutes/' + s}
